function fixture() { return { schemaVersion:1,status:'materialized_reviewed_package_qa_inputs',repository:'shannon0430/openclaw',finalOpenclawSourceCommit:c,cuaSourceCommit:CUA_HEAD,finalDllSha256:DLL,officialAddonSha256:ADDON,proposalManifestSha256:'a'.repeat(64),release:{id:1,draft:false,prerelease:true,makeLatest:false,targetCommitish:c,tag:'issue344-package-qa-'+c.slice(0,16)},eligibility:{schemaVersion:1,status:'accepted_for_isolated_package_qa_only',liveActivation:false,deploymentReady:false,windowsPackageQaAlreadyPassed:false,focusedNative:{repository:'shannon0430/cua',runId:38040866092,headSha:CUA_HEAD,workflowPath:'.github/workflows/issue344-keyboard-native-qa.yml',conclusion:'success',unitCasesPassed:668,ownedFixturesPassed:2,node:'24.19.0',rust:'1.97.1'},sourceRelease:{sourceCommit:c,version:'2026.9.6',fullBuildExit:0,packageCheckExit:0,normalPackageHelper:'scripts/package-openclaw-for-docker.mjs',completePluginSet:true,declarationsUiMetadata:true,selectionNarrowing:false,skipBuild:false},canonicalActivationGate:{repository:'shannon0430/cua',runId:38042245292,dispatchHeadSha:'27bbeaa4940c801da76645df952815b28143f011',sourceRef:CUA_HEAD,workflowPath:'.github/workflows/issue344-canonical-windows-all.yml',workflowSha256:'aca159f5198db42e26aa939b63c6903f5644a5115fec8f4fca5ef77f7107c223',dispatchBranch:'source/issue344-canonical-windows-qa-20261010',event:'workflow_dispatch',lane:'all',requireGui:true,noSkippedCasesRequired:true,activationEligibility:'pending_separate_live_acceptance'},immutableProofHashes:{...IMMUTABLE_PROOF_HASHES}},assets:Object.entries(ASSETS).map(([key,name],i)=>({key,name,id:i+10,bytes:TAR_BINDINGS[key]?.bytes??1,sha256:TAR_BINDINGS[key]?.sha256??'b'.repeat(64),state:'uploaded'})) }; }
const cases=[];function test(name,fn) { fn();cases.push(name); }
test('materialized_source_contract_only',()=>validateManifest(fixture()));
for(const [name,change] of [['pending_inputs',m=>m.status='pending'],['missing_commit',m=>m.finalOpenclawSourceCommit=null],['zero_digest',m=>m.assets[0].sha256='0'.repeat(64)],['duplicate_asset',m=>m.assets[1].id=m.assets[0].id],['missing_asset',m=>m.assets.pop()],['arbitrary_asset_name',m=>m.assets[0].name='../escape'],['draft_not_public_qa_prerelease',m=>m.release.draft=true],['native_pending',m=>m.eligibility.focusedNative.conclusion='in_progress'],['owned_fixture_missing',m=>m.eligibility.focusedNative.ownedFixturesPassed=1],['partial_build',m=>m.eligibility.sourceRelease.skipBuild=true],['fake_package_pass',m=>m.eligibility.windowsPackageQaAlreadyPassed=true],['oversized_asset',m=>m.assets[0].bytes=1073741825]]) test(name,()=>{const m=fixture();change(m);assert.throws(()=>validateManifest(m));});
test('sanitizer_preserves_unrun_false_and_omits_localpath',()=>{const a=sanitizePublicReceipt({result:'source_only',actualWindows:false,path:'/Users/owned/source',passed:32});assert.equal(a.actualWindows,false);assert.equal(a.result,'source_only');assert.equal(a.path,'[local_source_path_omitted]');assert.equal(a.passed,32);});
test('sanitizer_refuses_secret_field',()=>assert.throws(()=>sanitizePublicReceipt({secret:'fixture-not-a-real-secret'})));
test('projection_only_generic_source_proof_and_original_hash',()=>{const x=projectPublicReceipt('sourceRebakeReceipt',{status:'source_verified',sourceSha:c,tarSha256:'e'.repeat(64),deploymentReady:false,actualDellTask:{secret:'not-public'},rawXml:'private-fixture',tarPath:'/Users/owned/input'},'d'.repeat(64));assert.equal(x.immutablePrivateReceiptSha256,'d'.repeat(64));assert.equal(x.proof.deploymentReady,false);assert(!Object.hasOwn(x.proof,'actualDellTask'));assert(!JSON.stringify(x).includes('private-fixture'));assert(!JSON.stringify(x).includes('/Users/'));assert.equal(x.projection.createsNoNewExecutionEvidence,true);});
test('projection_refuses_path_in_allowed_field',()=>assert.throws(()=>projectPublicReceipt('sourceRebakeReceipt',{status:'source_verified',sourceSha:c,artifactKind:'/Users/private/proof'},'d'.repeat(64))));
test('frozen_tar_binding_drift_refused',()=>{const m=fixture();m.assets[0].sha256='e'.repeat(64);assert.throws(()=>validateManifest(m));});
test('other_valid_source_commit_refused',()=>{const m=fixture();m.finalOpenclawSourceCommit='f'.repeat(40);assert.throws(()=>validateManifest(m));});
test('private_extra_eligibility_top_field_refused',()=>{const m=fixture();m.eligibility.actualDellTask={private:'not-public'};assert.throws(()=>validateManifest(m));});
test('private_extra_eligibility_nested_field_refused',()=>{const m=fixture();m.eligibility.sourceRelease.rawXml='not-public';assert.throws(()=>validateManifest(m));});
test('pending_canonical_activation_not_a_disposable_qa_block',()=>{const m=fixture();validateManifest(m);assert.equal(m.eligibility.canonicalActivationGate.activationEligibility,'pending_separate_live_acceptance');assert.equal(m.eligibility.deploymentReady,false);});
test('public_projection_extra_private_field_refused',()=>{const x=projectPublicReceipt('sourceRebakeReceipt',{status:'source_verified',sourceSha:c,tarSha256:'e'.repeat(64)},PROOF_ORIGINALS.sourceRebakeReceipt);validatePublicProjection('sourceRebakeReceipt',x);x.privateReservation={not:'public'};assert.throws(()=>validatePublicProjection('sourceRebakeReceipt',x));});
